// Get text safely from previous node (supports both JSON and binary markdown)
let md = "";

// Case 1: Markdown came as text field in JSON
if (items[0]?.json?.output?.[0]?.content?.[0]?.text) {
  md = items[0].json.output[0].content[0].text;
}

// Case 2: Markdown came as binary file
else if (items[0]?.binary?.data) {
  md = Buffer.from(items[0].binary.data.data, 'base64').toString('utf8');
}

// Case 3: Markdown as plain text field
else if (items[0]?.json?.data) {
  md = items[0].json.data;
}

else {
  return [{ json: { error: "No markdown input found for cleaning" } }];
}

// Clean and format Markdown
