let output = [];

for (const item of items) {

  const out = item.json.stdout;
  if (!out) throw new Error("No stdout returned from Python script.");

  let parsed;
  try {
    parsed = JSON.parse(out);
  } catch (err) {
    throw new Error("Invalid JSON in stdout: " + out);
  }

  const arr = Array.isArray(parsed) ? parsed : [parsed];

  // Main PDF entry (not extracted images)
  const docInfo = arr.find(p => !p.isExtractedImage) || arr[0];

  //
  // 1️⃣  Create MAIN PDF ITEM
  //
  const pdfItem = {
    json: {
      ...item.json,
      parsedRaw: arr,
      parsedContainsImage: docInfo.containsImage,
      parsedImageCount: docInfo.imageCount,
      parsedImageFiles: docInfo.imageFiles
    },
    binary: item.binary || {}
  };

  output.push(pdfItem);

  //
  // 2️⃣  If extracted images exist → create separate items
  //
  const extractedImages = arr.filter(p => p.isExtractedImage);

  for (const img of extractedImages) {
    const imgItem = {
      json: {
        sourceDoc: img.sourceDoc || item.json.fileName,
        imageFile: img.file,
        isExtractedImage: true,
        imageCount: img.imageCount,
        imageFiles: img.imageFiles
      },
      binary: {}     // keep empty now — can attach actual binary later if required
    };

    output.push(imgItem);
  }
}

return output;

// n8n Code node (JavaScript) - Preprocessor + Balanced Summarizer + Token Estimator
// Input expected: items = [{ json: { mergedContext: "....", contextCount: N } }, ...]
// Outputs: mergedContextCleaned, originalChars, cleanedChars, originalTokens, cleanedTokens, summaryTokens, summary, sections[]

const STOPWORDS = new Set([
  "the","and","is","in","it","of","to","a","for","with","on","that","as","are","be","this","by","or","an","from",
  "at","we","will","should","can","which","their","have","has","not","but","if","they","these","such","may","also"
]);

function estimateTokensFromChars(chars) {
  // Practical approximation: 1 token ~= 4 characters
  // Adjust factor if you want more conservative estimate
  return Math.max(1, Math.ceil(chars / 4));
}

function splitToSentences(text) {
  // Simple sentence splitter - handles ., ?, !
  // Keep short sentences intact
  return text
    .replace(/\r\n/g, "\n")
    .replace(/\n+/g, "\n")
    .split(/(?<=[.?!])\s+(?=[A-Z0-9"'\(\[])/g)
    .map(s => s.trim())
    .filter(Boolean);
}

function scoreSentences(sentences, topNwords=120) {
  // Simple frequency-based scoring (extractive)
  const freq = {};
  for (const s of sentences) {
    const words = s.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(Boolean);
    for (const w of words) {
      if (STOPWORDS.has(w)) continue;
      freq[w] = (freq[w] || 0) + 1;
    }
  }
  // normalize and score
  const scores = sentences.map(s => {
    const words = s.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(Boolean);
    let sc = 0;
    for (const w of words) {
      if (freq[w]) sc += freq[w];
    }
    // length-normalize a bit
    sc = sc / Math.sqrt(Math.max(1, words.length));
    return sc;
  });
  return scores;
}

function dedupeParagraphs(paragraphs) {
  // Exact + lightweight fuzzy using trigram set Jaccard
  const seen = [];
  const out = [];
  function ngrams(text, n=3){
    const s = text.toLowerCase().replace(/\s+/g, " ").trim();
    const out = [];
    for (let i=0;i<s.length-(n-1);i++){
      out.push(s.slice(i,i+n));
    }
    return new Set(out);
  }
  for (const p of paragraphs) {
    const pnorm = p.trim();
    if (!pnorm) continue;
    let isDup = false;
    for (const s of seen) {
      if (pnorm === s.raw) { isDup = true; break; }
      // jaccard of char ngrams
      const a = ngrams(pnorm), b = s.ng;
      const inter = [...a].filter(x => b.has(x)).length;
      const union = new Set([...a, ...b]).size;
      const j = union === 0 ? 0 : inter/union;
      if (j > 0.85) { isDup = true; break; } // high threshold to avoid false positives
    }
    if (!isDup) {
      seen.push({ raw: pnorm, ng: ngrams(pnorm) });
      out.push(pnorm);
    }
  }
  return out;
}

function normalizeHeadingsAndRemoveUndefined(md) {
  // Remove "## undefined", orphan code fences; normalize \page markers
  let s = md.replace(/```(?:markdown)?/gi, "\n"); // remove code fences markers
  s = s.replace(/\\page/g, "\n\n---\n\n"); // unify page breaks
  // remove headings that are just 'undefined' or blank
  s = s.replace(/^(#{1,6})\s*(undefined)\s*$/gim, "");
  // collapse excessive newlines
  s = s.replace(/\n{3,}/g, "\n\n");
  return s.trim();
}

function splitIntoSections(text) {
  // If markdown headings exist (h2/h3), split by them; otherwise return single section
  const lines = text.split("\n");
  const sections = [];
  let curTitle = "Document";
  let curBuf = [];

  const headingRe = /^(#{1,6})\s*(.+)$/;
  for (let line of lines) {
    const m = line.match(headingRe);
    if (m) {
      // flush
      if (curBuf.length) {
        sections.push({ sectionName: curTitle, text: curBuf.join("\n").trim() });
      }
      curTitle = m[2].trim();
      curBuf = [];
    } else {
      curBuf.push(line);
    }
  }
  if (curBuf.length) sections.push({ sectionName: curTitle, text: curBuf.join("\n").trim() });
  return sections;
}

function summarizeExtractive(text, tokenBudget, mode="balanced") {
  // mode: 'concise' (more aggressive), 'balanced', 'detailed' (less aggressive)
  if (!text || !text.trim()) return { summary: "", tokens: 0, chars: 0 };

  const sentences = splitToSentences(text);
  if (sentences.length === 0) return { summary: "", tokens: 0, chars: 0 };

  const scores = scoreSentences(sentences);
  // pair and sort
  const pairs = sentences.map((s,i)=>({s, score: scores[i], idx:i, chars: s.length}));
  pairs.sort((a,b)=>b.score - a.score);

  // select sentences until tokenBudget reached (estimate)
  const chosen = [];
  let charsCount = 0;
  for (const p of pairs) {
    const estTokens = estimateTokensFromChars(p.chars);
    const currentTokens = estimateTokensFromChars(charsCount);
    if (currentTokens + estTokens > tokenBudget) continue;
    // Keep ordering by original index for readability
    chosen.push(p);
    charsCount += p.chars;
  }

  // If nothing selected (budget too small), pick top 1 sentence
  if (chosen.length === 0) {
    const top = pairs[0];
    chosen.push(top);
    charsCount = top.chars;
  }

  // Order chosen sentences by original order
  chosen.sort((a,b)=>a.idx - b.idx);
  const summary = chosen.map(x=>x.s).join(" ");

  return { summary: summary.trim(), tokens: estimateTokensFromChars(charsCount), chars: charsCount };
}

// -------------------- Main Node Logic --------------------

const inputs = items.map(i=>i.json);
const mergedRaw = inputs.map(i=>i.mergedContext || "").join("\n\n---\n\n");
const contextCount = inputs.reduce((acc,i)=> acc + (i.contextCount || 0), 0);

// 1) Normalize and remove obvious garbage
let cleaned = normalizeHeadingsAndRemoveUndefined(mergedRaw);

// 2) Break into paragraphs and dedupe
const paragraphs = cleaned.split(/\n{2,}/).map(p=>p.trim()).filter(Boolean);
const dedupedParas = dedupeParagraphs(paragraphs);

// rebuild cleaned context
cleaned = dedupedParas.join("\n\n");

// 3) Split into sections (by headings if any)
const sections = splitIntoSections(cleaned);

// If sections are just single 'Document' and very long, optionally try to chunk by length
// But for balanced mode we will still summarize

// 4) Compute sizes and token estimates
const originalChars = mergedRaw.length;
const cleanedChars = cleaned.length;
const originalTokens = estimateTokensFromChars(originalChars);
const cleanedTokens = estimateTokensFromChars(cleanedChars);

// 5) Summarize: balanced mode target
const TARGET_TOKENS_FOR_LLM = 6500; // <--- tune this to control LLM cost
// If cleanedTokens already less than target, return full cleaned text as summary-friendly
let summaryText = "";
let summaryTokens = 0;

// Option B = Balanced summarization: summarize per-section but preserve sections until budget
if (cleanedTokens <= TARGET_TOKENS_FOR_LLM) {
  summaryText = cleaned;
  summaryTokens = cleanedTokens;
} else {
  // Distribute budget across sections proportional to section size
  const sectionsInfo = sections.map(sec=>{
    const chars = sec.text.length;
    const tokens = estimateTokensFromChars(chars);
    return { sectionName: sec.sectionName, text: sec.text, chars, tokens };
  });

  const totalTokensSection = sectionsInfo.reduce((a,b)=>a + b.tokens, 0) || 1;
  const perSectionSummaries = [];
  let tokensUsed = 0;

  for (const s of sectionsInfo) {
    // allocate proportional budget but at least 80 tokens for small sections
    const alloc = Math.max(120, Math.floor((s.tokens / totalTokensSection) * (TARGET_TOKENS_FOR_LLM - 200)));
    const summ = summarizeExtractive(s.text, alloc, "detailed");
    perSectionSummaries.push({ sectionName: s.sectionName, summary: summ.summary, chars: summ.chars, tokens: summ.tokens });
    tokensUsed += summ.tokens;
  }

  // Build final summary text by joining section summaries
  summaryText = perSectionSummaries.map(s=> `## ${s.sectionName}\n\n${s.summary}`).join("\n\n");
  summaryTokens = tokensUsed;
}

// 6) Prepare section-level summaries for output (use smaller local budgets)
const sectionOutputs = sections.map(sec => {
  const secTokens = estimateTokensFromChars(sec.text.length);
  const budget = Math.max(60, Math.floor(Math.min(secTokens, 300))); // small budget per section
  const summ = summarizeExtractive(sec.text, budget, "detailed");
  return {
    sectionName: sec.sectionName,
    text: sec.text,
    chars: sec.text.length,
    tokens: estimateTokensFromChars(sec.text.length),
    summary: summ.summary,
    summaryChars: summ.chars,
    summaryTokens: summ.tokens
  };
});

// return single output item
return [
  {
    json: {
      mergedContextCleaned: cleaned,
      contextCount: contextCount,
      originalChars,
      cleanedChars,
      originalTokens,
      cleanedTokens,
      targetTokensForLLM: TARGET_TOKENS_FOR_LLM,
      summaryTokens,
      summary: summaryText,
      sections: sectionOutputs
    }
  }
];

