const md = items[0].json.cleanedMarkdown;

// regex that matches variations like whitespace, dashes, etc.
const stories = md.split(/\s*-*\s*USER_STORY_BREAK\s*-*\s*/g).map((block, i) => ({
  json: {
    storyIndex: i + 1,
    markdown: block.trim()
  }
}));

return stories;

const output = [];

items.forEach((item, index) => {
  const binaries = item.binary || {};
  const keys = Object.keys(binaries);

  if (keys.length === 0) {
    output.push({ json: { error: "No binary received" }});
    return;
  }

  keys.forEach(key => {
    const file = binaries[key];
    const base64 = file.data || file.fileData || "";

    let sampleText = "";

    try {
      // If file is an image, skip sample text extraction
      if ((file.mimeType || "").startsWith("image/")) {
        sampleText = "";  // Prevent junk output for images
      } else {
        const buffer = Buffer.from(base64, "base64");
        sampleText = buffer.toString("utf8", 0, 20000);
      }
    } catch (e) {
      sampleText = "";
    }

    output.push({
      json: {
        id: index,
        fileName: file.fileName || key,
        mimeType: file.mimeType || "",
        sampleText
      },
      binary: { data: file }
    });
  });
});

return output;

// Parse the agent output and attach the single binary object to all items

return items.map((item,index) => {
  let parsed = {};
  try {
    parsed = JSON.parse(item.json.output);
  } catch (e) {
    parsed = { error: "Invalid JSON returned", raw: item.json.output };
  }

 // Directly access matching binary from Convert Binaries to json output
  const source = $items("Convert Binaries to json")[index];
  const originalBinary = source?.binary || {};

  return {
    json: {
      ...parsed,
      id: index
    },
    binary: originalBinary
  };
});

