const output = [];

for (const item of items) {
  const binaries = item.binary || {};

  for (const [key, binary] of Object.entries(binaries)) {
    output.push({
      json: {
        fileName: binary.fileName || key,
        mimeType: binary.mimeType || '',
      },
      binary: {
        data: binary
      }
    });
  }
}

return output;

const documents = items.map(item => ({
  fileName: item.json.fileName,
  fileType: item.json.fileType,
  docType: item.json.docType,
  contentType: item.json.contentType,
  extractionType: item.json.extractionType,

  extractedText: item.json.extractedText,

  sections: item.json.sections,
  tables: item.json.tables,
  lists: item.json.lists,

  confidence: item.json.confidence
}));

return [
  {
    json: {
      documentCount: documents.length,
      documents
    }
  }
];

const results = [];

for (const inputItem of $input.all()) {
  if (!inputItem.json.output) {
    throw new Error("Missing 'output' field from extractor agent");
  }

  let parsed;

  // Case 1: Agent already returned an object
  if (typeof inputItem.json.output === "object") {
    parsed = inputItem.json.output;
  }

  // Case 2: Agent returned JSON as string
  else if (typeof inputItem.json.output === "string") {
    try {
      parsed = JSON.parse(inputItem.json.output.trim());
    } catch (e) {
      throw new Error(
        `Invalid JSON from extractor agent for one item. Raw output:\n${inputItem.json.output}`
      );
    }
  }

  else {
    throw new Error("Unsupported output type from extractor agent");
  }

  results.push({
    json: {
      fileName: parsed.fileName,
      fileType: parsed.fileType,
      docType: parsed.docType,
      contentType: parsed.contentType,
      extractionType: parsed.extractionType,

      extractedText: parsed.extractedText,
      sections: parsed.sections || [],
      tables: parsed.tables || [],
      lists: parsed.lists || [],

      confidence: parsed.confidence || 0
    }
  });
}

return results;

